using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using NetworkHub.App;
using NetworkHub.Dns;
namespace NetworkHub.Desktop;
internal static class TestsR2
{
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    internal static void Headless(Action<string,Action> test)
    {
        test("C process receipt preserves profile and accepts legacy unknown",()=>{var legacy=JsonSerializer.Deserialize<OwnedReceipt>("{\"Token\":\"legacy\",\"Pid\":1,\"StartFileTime\":2,\"Executable\":\"stub\",\"Module\":\"zapret\"}")!;Check(legacy.Profile=="","Legacy profile inferred");var receipt=legacy with{Profile="general (ALT13).bat"};Check(JsonSerializer.Deserialize<OwnedReceipt>(JsonSerializer.Serialize(receipt))!.Profile==receipt.Profile,"Restart lost running strategy");});
        test("C actual selected and unknown profiles remain distinct",()=>{Check(ModuleStatusLine.Description("ALT13","ALT2",true)=="ALT13 → ALT2","Pending profile hid actual");Check(ModuleStatusLine.Description("ALT13","ALT13",true)=="ALT13","Unchanged profile duplicated");Check(ModuleStatusLine.Description("","ALT2",true).EndsWith(" → ALT2"),"Legacy receipt guessed selected as active");Check(ModuleStatusLine.Description("ALT13","ALT2",false)=="ALT2","Stopped profile shown as active");});
        test("C DNS line never claims external or interrupted session as running",()=>{var fake=TestsDns.Fixture();var current=fake.State.With(DnsFamily.IPv4,new(DnsMode.Manual,DnsProfiles.All[0].IPv4,DnsProfiles.All[0].IPv4));Check(DnsPresentation.LineStatus(current,null)==L.T("Configured outside Open Net"),"External state claimed managed");var journal=new DnsJournal(1,Guid.NewGuid(),"test",fake.State,current,current,new[]{DnsFamily.IPv4},DnsPhase.Applied,null,"",""){ProfileId="comss",ProfileName="ComssDNS"};Check(DnsPresentation.LineStatus(current,journal)==L.T("Running"),"Verified managed session missing");Check(DnsPresentation.LineStatus(fake.State,journal)!=L.T("Running"),"Foreign change hidden");});
        test("R2 ALT ordering is numeric and keeps full names",()=>{var names=new[]{"general (ALT13)","general (ALT2)","general (ALT10)"}.OrderBy(WorkspaceController.NaturalKey).ToArray();Check(names[0].EndsWith("ALT2)")&&names[1].EndsWith("ALT10)"),"Lexical strategy ordering");});
        test("R2 DNS status separates external configuration from managed activity",()=>{var fake=TestsDns.Fixture();var state=fake.State.With(DnsFamily.IPv4,new(DnsMode.Manual,DnsProfiles.All[0].IPv4,DnsProfiles.All[0].IPv4));var journal=new DnsJournal(1,Guid.NewGuid(),"test",fake.State,state,state,new[]{DnsFamily.IPv4},DnsPhase.Applied,null,"",""){ProfileId="comss",ProfileName="ComssDNS"};Check(!DnsPresentation.Managed(state,null)&&DnsPresentation.Status(state,null).Contains("ComssDNS"),"External DNS claimed managed");Check(DnsPresentation.Managed(state,journal),"Verified session missing");Check(!DnsPresentation.Managed(fake.State,journal),"Foreign DNS claimed active");Check(!DnsPresentation.Managed(state,journal with{Phase=DnsPhase.Restoring}),"Unverified restoration claimed complete");});
        test("R2 basic profile preserves encryption and leaves plaintext source plaintext",()=>{var fake=TestsDns.Fixture();var comss=DnsProfiles.All.First(p=>p.Id=="comss");var magic=DnsProfiles.All.First(p=>p.Id=="magic");Check(DnsProfiles.ManualPlan(fake.State.IPv4,comss.IPv4,comss).Encryption.Length==0,"Unrequested DoH enabled");var encrypted=fake.State.IPv4 with{Encryption=fake.State.IPv4.Servers.Select(s=>new DnsDohSettings(s,comss.Doh,2)).ToArray()};Check(DnsProfiles.ManualPlan(encrypted,magic.IPv4,magic).Encryption.All(p=>p.Flags==2&&p.Template==magic.Doh),"DoH weakened");bool blocked=false;try{var geo=DnsProfiles.All.First(p=>p.Id=="geohide-eu");DnsProfiles.ManualPlan(encrypted,geo.IPv4,geo);}catch(DnsException){blocked=true;}Check(blocked,"Unverified DoH endpoint silently accepted");});
        test("R2 provider catalogue excludes retired RU endpoints and conflicting Astracat",()=>{Check(DnsProfiles.All.Any(p=>p.Id=="magic")&&DnsProfiles.All.Any(p=>p.Id=="geohide-eu"),"New presets missing");Check(!DnsProfiles.All.SelectMany(p=>p.IPv4).Any(ip=>ip is "159.194.200.33" or "193.233.112.67" or "135.106.217.200"),"Unverified or retired endpoint returned");Check(DnsProfiles.All.Where(p=>p.Id!="custom").All(p=>p.CheckedOn=="2026-10-24"),"Stale source date");});
    }
    internal static void Capture(FrameworkElement element,string path,double scale=1){element.UpdateLayout();var bitmap=new RenderTargetBitmap(Math.Max(1,(int)Math.Ceiling(element.ActualWidth*scale)),Math.Max(1,(int)Math.Ceiling(element.ActualHeight*scale)),96*scale,96*scale,PixelFormats.Pbgra32);var background=new DrawingVisual();using(var dc=background.RenderOpen())dc.DrawRectangle(ThemeManager.Brush("Surface"),null,new Rect(0,0,element.ActualWidth,element.ActualHeight));bitmap.Render(background);bitmap.Render(element);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var file=File.Create(path);encoder.Save(file);}
    internal static async Task Ui(Shell shell,AppFiles files,Func<string,Func<Task>,Task> test)
    {
        await test("R2 simple power saves original automatically switches profiles and reports failed restoration",async()=>{
            var saved=shell.Settings.Copy();var isolated=new AppFiles(Path.Combine(files.Root,"test-results/r2-power-"+Guid.NewGuid().ToString("N")));var fake=TestsDns.Fixture(isolated.Data);var original=fake.State;DnsManagerView.ReaderForTests=fake;DnsManagerView? view=null;
            try{var localized=saved.Copy();localized.Language="ru";localized.Theme="dark";shell.ApplySettings(localized);view=new DnsManagerView(shell,isolated);view.SelectProfile("comss");view.ConfirmationForTests=_=>true;view.Window.Show();view.Window.UpdateLayout();Check(!LocalizedTree.Walk(view.Window).OfType<Button>().Any(b=>b.Name is "DnsApply" or "DnsRestore"),"Competing actions remained on the main page");Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,"r2-dns-before.png"));
                await view.Power();Check(view.Applied&&fake.State.IPv4.Encryption.Length==0,"Plain source was unexpectedly encrypted or not applied");var store=new DnsFileJournalStore(Path.Combine(isolated.Data,"Dns/IsolatedRecovery"),"safe-test");Check(store.Load(original.AdapterId)!.Before.SameConfiguration(original),"Original was not saved automatically");view.Window.UpdateLayout();Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,"r2-dns-on.png"));
                view.SelectProfile("magic");Check(view.Applied&&view.Status.Contains("Comss"),"Selecting profile misreported actual state");await view.Power();Check(fake.State.IPv4.Servers.SequenceEqual(DnsProfiles.All.First(p=>p.Id=="magic").IPv4)&&store.Load(original.AdapterId)!.Before.SameConfiguration(original),"Profile switch overwrote original");
                ((ComboBox)view.Window.FindName("DnsSimulatedFailure")).SelectedIndex=3;bool restored=await view.Power(true);Check(!restored&&!fake.State.SameConfiguration(original)&&view.Status.Contains(L.T("Error")),"Failed restoration reported success");view.Window.UpdateLayout();Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,"r2-dns-restore-error.png"));((ComboBox)view.Window.FindName("DnsSimulatedFailure")).SelectedIndex=0;await view.OperationForTests(true);Check(fake.State.SameConfiguration(original),"Recovery did not restore manual original");view.Window.UpdateLayout();Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,"r2-dns-off.png"));
                File.WriteAllText(Path.Combine(files.Data,"r2-simulated-power.json"),JsonSerializer.Serialize(new{Simulation=true,Original=original,Restored=fake.State,Backup=store.Load(original.AdapterId),ActualWindowsDnsChanged=false,CacheWasNotCleared=true}));
                var advanced=view.OpenAdvanced();advanced.UpdateLayout();Capture((FrameworkElement)advanced.Content,Path.Combine(files.Data,"r2-dns-advanced.png"));advanced.Close();
            }finally{view?.Window.Close();DnsManagerView.ReaderForTests=null;shell.ApplySettings(saved);}
        });
        await test("R2 measured auto height and scrollbar gutter at 1 2 3 modules and long messages",()=>{var saved=shell.Settings.Copy();try{foreach(string language in new[]{"en","ru"})foreach(int count in new[]{1,2,3}){var next=saved.Copy();next.Language=language;next.Theme="dark";next.Backdrop="solid";next.Workspace.Visible=WorkspaceSettings.Modules.Take(count).ToArray();next.Workspace.ManualHeight=false;shell.ApplySettings(next);shell.Window.UpdateLayout();double height=shell.Window.Height;shell.ShowMessage("First line\nSecond line\nThird line is available in the tooltip");shell.Window.UpdateLayout();var scroll=shell.Find<ScrollViewer>("MainScroll");Check(scroll.ScrollableHeight<1,"Automatic rows require scrolling");Check(shell.Window.Height==height,"Status changed window height");var footer=shell.Find<Button>("Settings");Check(footer.TranslatePoint(new Point(0,footer.ActualHeight),shell.Window).Y<=shell.Window.ActualHeight,"Footer clipped");foreach(double scale in new[]{1d,1.25,1.5})Capture((FrameworkElement)shell.Window.Content,Path.Combine(files.Data,$"r2-main-{language}-{count}-{scale}.png"),scale);}
            var manual=saved.Copy();manual.Workspace.ManualHeight=true;manual.Workspace.Height=450;shell.ApplySettings(manual);shell.Window.UpdateLayout();var viewer=shell.Find<ScrollViewer>("MainScroll");var bar=viewer.Template.FindName("PART_VerticalScrollBar",viewer) as ScrollBar;Check(bar!=null,"Manual overflow did not expose scrolling");double edge=bar!.TranslatePoint(new Point(),viewer).X;foreach(string id in new[]{"ZapretCheck","TgCheck"}){var control=shell.Find<CheckBox>(id);Check(control.TranslatePoint(new Point(control.ActualWidth,0),viewer).X<=edge-3,"Scrollbar overlaps action control");}File.WriteAllText(Path.Combine(files.Data,"r2-dpi.json"),JsonSerializer.Serialize(new{ActualDpi=VisualTreeHelper.GetDpi(shell.Window).PixelsPerInchX,RenderedScales=new[]{1,1.25,1.5},PhysicalDpiNotChanged=true}));
        }finally{shell.ApplySettings(saved);}return Task.CompletedTask;});
        await test("R2 all workspace menus keep themed foreground and bounded scrolling",async()=>{var saved=shell.Settings.Copy();try{string directory=Path.Combine(files.Data,"menu-fixture");Directory.CreateDirectory(directory);for(int i=1;i<=40;i++)File.WriteAllText(Path.Combine(directory,$"general (ALT{i}).bat"),"Owned listing fixture; never executed");foreach(string theme in new[]{"dark","light"}){var next=saved.Copy();next.Theme=theme;next.Language="ru";next.Backdrop="solid";next.ZapretDirectory=directory;shell.ApplySettings(next);foreach(string name in new[]{"ZapretQuick","DnsQuick","MainAssignment"}){var button=shell.Find<Button>(name);button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var menu=button.ContextMenu!;try{await Task.Delay(40);menu.UpdateLayout();Check(menu.IsOpen&&menu.ActualHeight<=361,"Unbounded popup");foreach(MenuItem item in menu.Items){Check(((SolidColorBrush)item.Foreground).Color==((SolidColorBrush)ThemeManager.Brush("Text")).Color,"Black/default menu text");}if(name=="ZapretQuick"){var headers=menu.Items.OfType<MenuItem>().Select(m=>m.Header.ToString()).ToArray();Check(Array.IndexOf(headers,"general (ALT2)")<Array.IndexOf(headers,"general (ALT10)"),"ALT order");}Capture(menu,Path.Combine(files.Data,$"r2-menu-{name}-{theme}.png"));}finally{menu.IsOpen=false;}}}}finally{shell.ApplySettings(saved);}});
        await test("R2 secondary windows restore and explicitly closed panels stay closed",async()=>{var settings=shell.OpenSettings();shell.Workspace.OpenManager();var modules=shell.Window.OwnedWindows.Cast<Window>().Single(w=>w.FindName("Visibledns")!=null);var dns=shell.OpenDnsSettings();try{shell.HideToTray();Check(!settings.IsVisible&&!modules.IsVisible&&!dns.IsVisible,"Owned panel left visible in tray");modules.Close();shell.Restore();await Task.Delay(120);Check(settings.IsVisible&&dns.IsVisible&&!shell.Window.OwnedWindows.Cast<Window>().Contains(modules),"Closed window recreated or existing panel lost");shell.Window.WindowState=WindowState.Minimized;await Task.Delay(60);shell.Restore();await Task.Delay(100);Check(settings.IsVisible&&dns.IsVisible,"Minimize lost child window");var version=(TextBlock)settings.FindName("ApplicationVersion");Check(version.Text==BuildInfo.Caption&&version.Text.Contains("0.4.0"),"Stale hardcoded version");}finally{settings.Close();dns.Close();}});
        await test("R2 drag editor cancels safely and does not launch any tools",()=>{var saved=shell.Settings.Copy();int launches=shell.Runtime.LaunchCount;var window=SettingsLayout.Create(shell,"Drag fixture",360);var editor=new ModuleOrderEditor(shell.Window,WorkspaceSettings.Modules);window.Content=editor;window.Show();window.UpdateLayout();try{editor.DragForTests("zapret",180,true);Check(editor.Order.SequenceEqual(WorkspaceSettings.Modules),"Cancelled drag changed order");editor.DragForTests("zapret",180);Check(editor.Order.Last()=="zapret"&&shell.Runtime.LaunchCount==launches,"Drag failed or launched tools");Capture((FrameworkElement)window.Content,Path.Combine(files.Data,"r2-reorder.png"));}finally{window.Close();shell.ApplySettings(saved);}return Task.CompletedTask;});
    }
}

